-- ============================================================================
-- V1 - Baseline: the BackTrack schema exactly as it existed before the
--      offline-first work (previously produced by Hibernate ddl-auto=update).
--
-- A database that already contains these tables is adopted by Flyway through
-- spring.flyway.baseline-on-migrate=true: this script is then recorded as
-- applied and NOT executed, so no existing data is touched.
-- Only a brand new, empty database actually runs it.
--
-- Do not edit this file. Add a new V{n}__*.sql migration instead.
-- ============================================================================

create table product_categories (
    id bigserial primary key,
    name varchar(80) not null,
    constraint uk_product_categories_name unique (name)
);

create table users (
    id bigserial primary key,
    username varchar(50) not null,
    password_hash varchar(100) not null,
    full_name varchar(120) not null,
    email varchar(120),
    role varchar(20) not null,
    active boolean not null,
    can_manage_customers boolean not null,
    created_at timestamp(6) with time zone not null,
    updated_at timestamp(6) with time zone,
    constraint uk_users_username unique (username)
);

create table customers (
    id bigserial primary key,
    name varchar(120) not null,
    phone varchar(30),
    email varchar(120),
    address varchar(255),
    notes varchar(500),
    archived boolean not null,
    created_at timestamp(6) with time zone not null,
    updated_at timestamp(6) with time zone
);

create table products (
    id bigserial primary key,
    sku varchar(40) not null,
    name varchar(150) not null,
    description varchar(500),
    category_id bigint,
    selling_price numeric(12, 2) not null,
    cost_price numeric(12, 2) not null,
    stock_quantity integer not null,
    min_stock_level integer not null,
    archived boolean not null,
    created_at timestamp(6) with time zone not null,
    updated_at timestamp(6) with time zone,
    constraint uk_products_sku unique (sku),
    constraint fk_products_category foreign key (category_id) references product_categories (id)
);

create table sales (
    id bigserial primary key,
    sale_number varchar(30) not null,
    customer_id bigint,
    cashier_id bigint not null,
    status varchar(20) not null,
    payment_status varchar(20) not null,
    payment_method varchar(20) not null,
    subtotal numeric(12, 2) not null,
    discount_amount numeric(12, 2) not null,
    total_amount numeric(12, 2) not null,
    amount_paid numeric(12, 2) not null,
    change_amount numeric(12, 2) not null,
    notes varchar(500),
    created_at timestamp(6) with time zone not null,
    cancelled_at timestamp(6) with time zone,
    cancelled_by bigint,
    cancel_reason varchar(255),
    constraint uk_sales_sale_number unique (sale_number),
    constraint fk_sales_customer foreign key (customer_id) references customers (id),
    constraint fk_sales_cashier foreign key (cashier_id) references users (id),
    constraint fk_sales_cancelled_by foreign key (cancelled_by) references users (id)
);

create table sale_items (
    id bigserial primary key,
    sale_id bigint not null,
    product_id bigint not null,
    product_name varchar(150) not null,
    sku varchar(40) not null,
    unit_price numeric(12, 2) not null,
    quantity integer not null,
    line_total numeric(12, 2) not null,
    constraint fk_sale_items_sale foreign key (sale_id) references sales (id),
    constraint fk_sale_items_product foreign key (product_id) references products (id)
);

create table payments (
    id bigserial primary key,
    sale_id bigint not null,
    amount numeric(12, 2) not null,
    method varchar(20) not null,
    note varchar(255),
    recorded_by bigint,
    paid_at timestamp(6) with time zone not null,
    constraint fk_payments_sale foreign key (sale_id) references sales (id),
    constraint fk_payments_recorded_by foreign key (recorded_by) references users (id)
);

create table stock_movements (
    id bigserial primary key,
    product_id bigint not null,
    type varchar(20) not null,
    quantity_change integer not null,
    resulting_stock integer not null,
    reason varchar(255),
    reference varchar(60),
    performed_by bigint,
    created_at timestamp(6) with time zone not null,
    constraint fk_stock_movements_product foreign key (product_id) references products (id),
    constraint fk_stock_movements_performed_by foreign key (performed_by) references users (id)
);

create table number_sequences (
    name varchar(40) not null primary key,
    next_value bigint not null,
    version bigint not null
);

create table business_settings (
    id bigint not null primary key,
    business_name varchar(150) not null,
    address varchar(255),
    contact_number varchar(40),
    email varchar(120),
    currency varchar(10) not null,
    logo_url varchar(255),
    receipt_footer varchar(255),
    default_min_stock_level integer not null,
    updated_at timestamp(6) with time zone
);
